-- RESEARCH-CLUSTER-CLOSEOUTS-2 (2026-10-26, session rem-a1, pillar research; agent_issues 100625). The closing probe of PARK-REARM-1 leaves rows in an unclaimable orphan state was the closure-observing template (superseded).
-- The diagnosis of the issue does not hold for current code (finding of 2026-10-26, confirmed here): the queued-row claim has no stage filter, resumeStage keeps a resumable stage, and the 11 rows that are queued at revise, review, verify or
-- complete all have a research_ready entry (the ready-queue window of RESEARCH-BACKPRESSURE-1) or are deferred; they wait for the research budget, not for a claim path (rem-rev-b9f3a431 was claimed and parked 15 times in 2880 minutes
-- from exactly that state). What stays measurable is the orphan the issue describes (a queued row at a resumable stage that no ready window or deferral covers, older than a day) and the re-arm ceiling its second measure names
-- (terminal_rearms above 2 on a live row; PARK-REARM-CAP-1, research-exec 0.36.7, stops new ones; 1 live row from before it remains and ends when it publishes or parks). Both read 0 only when the defect is absent.
-- Rows written: remediation_contracts 1 (upsert on class issue-100625), decision_log 1. No DELETE, no DROP.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET status = 'superseded', last_verdict = 'superseded:rollback RESEARCH-CLUSTER-CLOSEOUTS-2' WHERE class = 'issue-100625' AND precondition LIKE 'RESEARCH-CLUSTER-CLOSEOUTS-2%';

INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at)
VALUES ('issue-100625', 100625, 'RESEARCH-CLUSTER-CLOSEOUTS-2: no queued row at a resumable stage is invisible to the ready window, and no live row passes the re-arm ceiling (issue 100625)', 'none: PARK-REARM-CAP-1 (research-exec 0.36.7) counts re-arms in terminal_rearms; the claim path has no stage filter; the rows that wait are inside the research_ready window and wait for the daily research budget', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM research_queue q WHERE q.status = ''queued'' AND q.stage IN (''revise'', ''review'', ''verify'', ''complete'') AND q.claimed_at IS NULL AND q.id NOT IN (SELECT id FROM research_ready) AND q.created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-1440 minutes'')) + (SELECT COUNT(*) FROM research_queue WHERE terminal_rearms > 2 AND status IN (''queued'', ''deferred'', ''researching'', ''review'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-research-exec', 1, 'active', datetime('now'))
ON CONFLICT (class) DO UPDATE SET issue_id = excluded.issue_id, precondition = excluded.precondition, action = excluded.action, verify_probe = excluded.verify_probe, verify_transport = excluded.verify_transport, escalate_to = excluded.escalate_to, max_attempts = excluded.max_attempts, expected_cadence_h = excluded.expected_cadence_h, status = 'active', last_verdict = NULL, last_attempt_at = NULL, attempts = 0, next_due_at = datetime('now'), module = NULL, deferred_since = NULL;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session-rem-a1', 'an issue whose diagnosis no longer reproduces closes on a probe of the defect it names, not on its status', 'RESEARCH-CLUSTER-CLOSEOUTS-2: issue 100625 gets a probe that counts queued rows at a resumable stage outside the ready window (older than a day) plus live rows above the re-arm ceiling', 'research_queue 2026-10-26 19:40Z: 11 rows queued at revise, review, verify or complete, every one with a research_ready entry or deferred; orphans 0; terminal_rearms above 2 on 1 row (live); the claim query has no stage filter (qnfo-research-exec claimNew); rem-rev-b9f3a431 was claimed and parked 15 times from that state', 'applied by migration', 'one remediation_contracts row', 'the Rollback line of migrations/2026-10-26-research-cluster-closeouts-2.sql supersedes the contract again', 'an orphan-state issue is closed on a measurement of orphans', 'the probe reads 1 now (the live row above the ceiling) and 0 when that row publishes or parks; issue 100625 then closes by the remediation tick', 'research throughput: a claim path that cannot see a row would show here', 'research_queue and research_ready read on 2026-10-26; the offline suite runs the probe on node:sqlite'
WHERE NOT EXISTS (SELECT 1 FROM decision_log x WHERE x.action LIKE 'RESEARCH-CLUSTER-CLOSEOUTS-2:%');
